def build_quant_analysis(random_cfg, item_cfg):
    """Compute a transparent config-level baseline, not a live-player simulation."""
    items = []
    for item in item_cfg:
        code = str(item["Code"])
        items.append({
            "code": code,
            "level": int(code[-2:]),
            "price": item.get("Price", 0),
            "weight": item.get("Weight", 0),
            "energy": 2 ** (int(code[-2:]) - 1),
        })
    # Type 12/15/16 omit ItemAmounts; the applicable level-11
    # OrderItemNumberWeightConfig row is 30%/30%/40%.
    generic_amounts = {"one": 30, "two": 30, "three": 40}

    def position(lo, hi):
        pool = [x for x in items if x["weight"] > 0 and lo <= x["level"] <= hi]
        total_weight = sum(x["weight"] for x in pool)
        if not pool or not total_weight:
            return {"min": lo, "max": hi, "count": 0, "weight": 0, "mean_gold": None, "mean_energy": None, "levels": {}}
        return {
            "min": lo, "max": hi, "count": len(pool), "weight": total_weight,
            "candidate_weight": sorted({x["weight"] for x in pool}),
            "weight_share_each": pool[0]["weight"] / total_weight,
            "mean_gold": sum(x["price"] * x["weight"] for x in pool) / total_weight,
            "mean_energy": sum(x["energy"] * x["weight"] for x in pool) / total_weight,
            "levels": {str(level): sum(1 for x in pool if x["level"] == level) for level in range(lo, hi + 1) if any(x["level"] == level for x in pool)},
        }

    result = []
    for cfg in random_cfg:
        amount = cfg.get("ItemAmounts")
        amount_source = "OrderRandomConfig.ItemAmounts" if amount else "OrderItemNumberWeightConfig(level 11)"
        if amount:
            amounts = {"one": amount.get("OneItemWeight", 0), "two": amount.get("TwoItemsWeight", 0), "three": amount.get("ThreeItemsWeight", 0)}
        else:
            amounts = generic_amounts
        for index, filt in enumerate(cfg.get("Filters", []), 1):
            if not filt:
                result.append({"type": cfg["Type"], "filter": index, "amounts": amounts, "amount_source": amount_source, "positions": [], "expected_gold": None, "expected_energy": None, "gold_per_energy": None})
                continue
            positions = []
            for name in ("First", "Second", "Third"):
                hi = filt.get(name + "Max")
                if hi is None:
                    continue
                lo = filt.get(name + "Min", 1)
                positions.append(position(lo, hi))
            expected_gold = expected_energy = 0
            for idx, item_position in enumerate(positions):
                # First is mandatory; a 3-item order contains the second item too.
                probability = 1 if idx == 0 else ((amounts["two"] + amounts["three"]) if idx == 1 else amounts["three"]) / 100
                expected_gold += probability * (item_position["mean_gold"] or 0)
                expected_energy += probability * (item_position["mean_energy"] or 0)
            result.append({
                "type": cfg["Type"], "filter": index, "filter_config": filt, "amounts": amounts, "amount_source": amount_source,
                "positions": positions, "expected_gold": expected_gold, "expected_energy": expected_energy,
                "expected_count": (amounts["one"] + 2 * amounts["two"] + 3 * amounts["three"]) / 100,
                "gold_per_energy": expected_gold / expected_energy if expected_energy else None,
            })
    summaries = []
    for type_id in sorted({x["type"] for x in result}):
        rows = [x for x in result if x["type"] == type_id and x["positions"]]
        if not rows:
            continue
        summaries.append({"type": type_id, "filter_count": len(rows),
            "expected_gold_min": min(x["expected_gold"] for x in rows), "expected_gold_max": max(x["expected_gold"] for x in rows),
            "expected_energy_min": min(x["expected_energy"] for x in rows), "expected_energy_max": max(x["expected_energy"] for x in rows),
            "gold_per_energy_min": min(x["gold_per_energy"] for x in rows), "gold_per_energy_max": max(x["gold_per_energy"] for x in rows),
            "first_level_min": min(x["positions"][0]["min"] for x in rows), "first_level_max": max(x["positions"][0]["max"] for x in rows)})
    special = [{**x, "net_energy": x["energy"] - x["energy_reward"], "gem_per_net_energy": x["reward_gems"] / (x["energy"] - x["energy_reward"])} for x in SPECIAL_ORDERS]
    return {"filters": result, "summaries": summaries, "special_orders": special, "activity_orders": ACTIVITY_ORDERS, "formulas": [
        "P(candidate i | position, filter) = Weight_i / sum(Weight_j) over eligible Weight>0 candidates.",
        "E[gold] = E[gold(First)] + P(2 items)·E[gold(Second)] + P(3 items)·E[gold(Second)+gold(Third)]. First is always required.",
        "E[energy] uses the same position probabilities, with energy(L)=2^(L-1) base pieces.",
        "Gold / energy = E[gold] / E[energy]; filters are not averaged because their live selection probabilities are state-dependent.",
    ], "assumptions": [
        "候选池取 OrderItemConfig 中 Weight>0 的全部标准棋子；按配置 Weight 加权。",
        "基础子体=1体力，等级L棋子消耗 2^(L-1) 个基础子体；不计棋盘已有库存、生产器免费产出、订单互斥和重复权重动态衰减。",
        "普通随机订单按 First 必选，Second/Third 按 ItemAmounts 或 OrderItemNumberWeightConfig(level 11: 30/30/40) 的数量权重计入。",
        "当前标准候选的 Weight 均为100（Weight=0已排除），因此候选概率=1/候选总数；若未来出现不同Weight，按公式归一化。",
        "该结果是配置级理论期望，不是某个玩家状态下的实测掉落概率。",
    ]}


def fmt_seconds(value: int) -> str:
    if value < 60:
        return f"{value} 秒"
    if value % 3600 == 0:
        return f"{value // 3600} 小时"
    return f"{value // 60} 分钟"


def filter_condition_text(filt: dict) -> str:
    parts = []
    if "PlayerMin" in filt or "PlayerMax" in filt:
        parts.append(f"Player {filt.get('PlayerMin', '—')}–{filt.get('PlayerMax', '—')}")
    if "DiffSumMin" in filt or "DiffSumMax" in filt:
        parts.append(f"DiffSum {filt.get('DiffSumMin', '—')}–{filt.get('DiffSumMax', '—')}")
    if "sMonthPay" in filt or "eMonthPay" in filt:
        parts.append(f"MonthPay {filt.get('sMonthPay', '—')}–{filt.get('eMonthPay', '—')}")
    return "；".join(parts) if parts else "无 Player/DiffSum/MonthPay 条件"


def main() -> None:
    random_cfg = json.loads((DATA_DIR / "OrderRandomConfig.json").read_text(encoding="utf-8"))
    fixed_cfg = json.loads((DATA_DIR / "OrderFixedConfig.json").read_text(encoding="utf-8"))
    rows = []
    for cfg in random_cfg:
        code, label, mechanism = TYPE_META.get(cfg["Type"], (f"Type{cfg['Type']}", "未映射类型", "待确认"))
        rows.append({
            "type": cfg["Type"], "code": code, "label": label,
            "unlock": cfg["UnlockLevel"], "refresh": cfg["RefreshTime"],
            "refresh_text": fmt_seconds(cfg["RefreshTime"]),
            "filter_count": len(cfg.get("Filters", [])),
            "filters": cfg.get("Filters", []),
            "item_amounts": cfg.get("ItemAmounts"), "mechanism": mechanism,
        })
    quant = build_quant_analysis(random_cfg, json.loads((DATA_DIR / "OrderItemConfig.json").read_text(encoding="utf-8")))
    slot_map = {1: "Slot1", 2: "Slot2 / Slot3", 3: "Slot4", 4: "Slot5", 9: "Slot8", 12: "CharacterIntimacySlot", 15: "活动指定普通槽", 16: "TimedOrderSlot13", 21: "活动指定槽"}
    merged_orders = []
    for item in quant["filters"]:
        base = next((row for row in rows if row["type"] == item["type"]), {"code": f"Type{item['type']}", "label": "未映射类型", "unlock": "—", "refresh_text": "—", "item_amounts": None, "mechanism": "待确认"})
        merged_orders.append({
            **item,
            "code": base["code"], "label": base["label"], "unlock": base["unlock"],
            "refresh_text": base["refresh_text"], "slot": slot_map.get(item["type"], "—"),
            "mechanism": base["mechanism"], "condition_text": filter_condition_text(item.get("filter_config", {})),
        })
    data = {"random_orders": rows, "merged_orders": merged_orders, "fixed_orders": fixed_cfg, "quant": quant,
            "source": "Gossip Harbor 3.98.10 · OrderRandomConfig / OrderFixedConfig / OrderItemConfig / MainOrderCreatorRandom"}
    embedded = json.dumps(data, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")
    OUTPUT_DIR.mkdir(exist_ok=True)
    html = TEMPLATE.replace("__EMBEDDED_DATA__", embedded)
    html = html.replace('<button class="tab" aria-selected="true" data-tab="matrix">刷新矩阵</button>', '<button class="tab" aria-selected="true" data-tab="matrix">刷新矩阵（定量+机制）</button>')
    html = html.replace('<button class="tab" aria-selected="false" data-tab="quant">定量期望</button>', '<button class="tab" aria-selected="false" data-tab="quant">定量明细</button>')
    html = html.replace('<th>内类型</th><th>中文归类</th><th class="num">解锁等级</th><th class="num">RefreshTime</th><th>Filter 档数</th><th>件数权重</th><th>机制摘要</th>', '<th>内类型</th><th>槽位</th><th>Filter</th><th>Filter 条件（AND）</th><th>解锁等级</th><th>RefreshTime/CD</th><th>First / Second / Third</th><th>数量权重</th><th>候选数</th><th>期望金币</th><th>期望体力</th><th>金币/体力</th>')
    html = html.replace('colspan="7">没有匹配类型', 'colspan="12">没有匹配 Filter')
    html = html.replace('const rs=d.random_orders.filter', 'const rs=d.merged_orders.filter')
    html = html.replace('x.code+x.label', 'x.code+x.label+x.condition_text')
    html = html.replace("<tr><td><strong>${x.code}</strong><span class=\"muted\">Type ${x.type}</span></td><td>${x.label}</td><td class=\"num\">Lv.${x.unlock}</td><td class=\"num\">${x.refresh_text}</td><td class=\"num\">${x.filter_count}</td><td>${x.item_amounts?`1件 ${x.item_amounts.OneItemWeight}% / 2件 ${x.item_amounts.TwoItemsWeight}%`:'—'}</td><td>${x.mechanism}</td></tr>", "<tr><td><strong>${x.code}</strong><span class=\"muted\">Type ${x.type}</span></td><td>${x.slot}</td><td>Filter ${x.filter}</td><td>${x.condition_text}</td><td class=\"num\">Lv.${x.unlock}</td><td class=\"num\">${x.refresh_text}</td><td>${x.positions.length?x.positions.map(p=>`${p.min}-${p.max}`).join(' / '):'—'}</td><td>${x.amounts.one}% / ${x.amounts.two}% / ${x.amounts.three}%</td><td class=\"num\">${x.positions.reduce((a,p)=>a+(p.count||0),0)}</td><td class=\"num\">${x.expected_gold==null?'—':x.expected_gold.toFixed(2)}</td><td class=\"num\">${x.expected_energy==null?'—':x.expected_energy.toFixed(2)}</td><td class=\"num\">${x.gold_per_energy==null?'—':x.gold_per_energy.toFixed(4)}</td></tr>")
    fill_scan_markup = r'''<div class="section"><h2>一次补位扫描会创建一张，还是创建所有能创建的？</h2><div class="note"><strong>明确答案：会尽量创建所有当前能创建的订单，不是成功一张就停。</strong>程序按 Slot1 → Slot19 依次检查；某个空槽成功创建后仍继续检查后面的槽。只要这一整轮创建过至少一张，程序还会重新从 Slot1 开始扫描；直到某一整轮一张都没有创建才结束。</div><div class="flow"><div class="step"><h3>第 1 轮开始</h3><span>把“本轮是否创建过订单”设为否。</span></div><div class="arrow">→</div><div class="step"><h3>扫描 1–19</h3><span>只处理空槽或 Finished 槽；逐槽调用各自创建器。</span></div><div class="arrow">→</div><div class="step"><h3>成功就落位</h3><span>立即写入该槽，但不 return，继续扫描后续槽。</span></div><div class="arrow">→</div><div class="step"><h3>判断整轮结果</h3><span>本轮有创建：回到 Slot1；本轮零创建：结束。</span></div></div><h3>完整例子</h3><ol class="list"><li>扫描开始时，Slot1、Slot4、Slot13、Slot15 都为空。</li><li>走到 Slot1：Random1 条件满足，创建 1 张；程序继续，不停止。</li><li>走到 Slot4：Random3 的 CD 未到，失败；程序继续，失败也不阻塞后续槽。</li><li>走到 Slot13：正处于“浣熊出没”活动，活动模型允许，创建 1 张 TimedOrder；程序继续。</li><li>走到 Slot15：Baseline 计时器还是 -1，只记录当前时间，本轮不创建。</li><li>第一轮扫描完，共创建 Random1 + TimedOrder 两张。因为本轮创建过订单，程序重新从 Slot1 开始第二轮。</li><li>第二轮中 Slot1、Slot13 已被占用；Random3 仍在 CD，Baseline 也未满 60 秒。整轮零创建，扫描结束。</li></ol><p class="formula">一次补位事件 = 重复完整扫描 Slot1..19，直到“整轮新增订单数 = 0”</p><p class="muted">“所有能创建”指执行到该槽时仍满足条件，并非先拍一张并行快照。每个槽最多同时放一张；前面槽位的创建也可能改变后面槽位的跨订单候选判断。</p></div><div class="section"><h2>什么时候会触发补位扫描？</h2><p><strong>一句话：</strong>补位扫描是“被事件叫醒的一次遍历”，不是每秒后台自动把所有槽位重抽一遍。扫描只负责检查空槽/已完成槽；某槽达到 CD 只是获得尝试资格，仍可能创建失败。</p><div class="table-wrap"><table><thead><tr><th>触发来源</th><th>何时发生</th><th>扫描动作</th><th>确定性</th></tr></thead><tbody><tr><td>订单系统初始化 / LateInit</td><td>订单数据同步完成、模型进入 LateInit</td><td>遍历逻辑槽位 1..19，尝试填充空槽</td><td><strong>代码直接调用</strong></td></tr><tr><td>完成任意订单</td><td><code>FinishOrder()</code> 将订单标记 Finished 后立即调用</td><td>清理该槽位并尝试创建新订单；本轮可能连续填多个空槽</td><td><strong>代码直接调用</strong></td></tr><tr><td>玩家升级</td><td>收到 <code>LevelUp</code> 事件</td><td>重新检查所有可补位槽位，可能让新解锁类型开始尝试</td><td><strong>事件监听已确认</strong></td></tr><tr><td>OrderBoost 补单事件</td><td>教程/活动触发 <code>OrderBoostFillOrder</code></td><td>立即再次遍历槽位</td><td><strong>事件监听已确认</strong></td></tr><tr><td>强制补位事件</td><td>系统或活动派发 <code>ForceTryFillOrders</code></td><td>立即再次遍历槽位</td><td><strong>事件监听已确认</strong></td></tr><tr><td>UpdatePerSecond 兜底</td><td>每秒更新函数运行且 <code>m_orders == nil</code>（订单容器尚未初始化/恢复异常）</td><td>调用一次补位；正常运行中 <code>m_orders</code> 已存在时不会每秒扫描</td><td><strong>代码直接确认，非正常刷新计时器</strong></td></tr></tbody></table></div><div class="section"><h3>扫描不等于生成：三个具体例子</h3><ol class="list"><li><strong>扫描到 Slot4（Random3），但 CD 未到：</strong>只检查一次，Random3 不生成；不会因为本轮扫描而提前重置 CD。</li><li><strong>扫描到 Slot15（Baseline），首次计时器为 -1：</strong>只写入当前时间并返回失败；60 秒只是下一次尝试的资格门槛，不会单独触发扫描。</li><li><strong>扫描到空的活动槽：</strong>活动未开放或远端 <code>CanCreateOrder</code> 返回 false，活动槽保持空；不会改抽成 Random1。</li></ol><p class="formula">单轮扫描 = 按槽位顺序检查；每个空/Finished 槽独立尝试；某槽失败不阻塞其它槽。完整补位事件 = 重复单轮扫描，直到一整轮没有创建任何新订单。</p></div><div class="section"><h3>最容易误解的边界</h3><ul class="list"><li>“完全没有订单”不是扫描触发条件；有订单也可以因升级、完成或强制事件扫描。</li><li>“所有 Random 都在 CD”不是扫描触发条件；扫描照样会发生，只是这些 Random 在各自创建器中失败。</li><li>普通订单完成后，<code>FinishOrder</code> 会触发扫描；但某个槽位创建失败不会自动换成别的类型。</li><li>当前代码未发现“每 60 秒自动调用补位扫描”的证据；Baseline 的 60 秒是资格门槛，不是全局定时器。</li></ul></div></div>'''
    baseline_markup = r'''<div class="section"><h2>BaselineOrder 完整机制：它是“库存清理单”</h2><div class="note"><strong>先记住：</strong>Baseline 不会像 Random 一样先定等级、再要求你生产一个新棋子。它只看你主棋盘和仓库里已经持有的棋子，从“扣掉其它当前订单已经需求的数量后，仍有足够富余”的棋子里随机挑一种，让你交出现货换金币。</div><div class="flow"><div class="step"><h3>1 · Slot15 空</h3><span>只有专属 Slot15 没有订单时才会尝试。</span></div><div class="arrow">→</div><div class="step"><h3>2 · 等待资格</h3><span>首次扫描只启动计时；至少 60 秒后还要再遇到补位扫描。</span></div><div class="arrow">→</div><div class="step"><h3>3 · 统计持有量</h3><span>按 Code 汇总主棋盘 + 仓库中的现有棋子数量。</span></div><div class="arrow">→</div><div class="step"><h3>4 · 扣除预占量</h3><span>统计所有当前订单对同一 Code 的需求数量，并从持有量中扣掉。</span></div><div class="arrow">→</div><div class="step"><h3>5 · 随机出单</h3><span>剩余量达到 RecommendedNumber 的 Code 进入池；等概率选一个。</span></div></div><h3>“可用候选”的精确定义</h3><p>某个棋子 Code 同时满足以下条件，才是 Baseline 的可用候选：</p><ol class="list"><li>它实际存在于玩家的<strong>主棋盘或仓库</strong>中；代码调用参数会把两处数量合并。</li><li>它在 <code>OrderItemConfig</code> 中存在。</li><li>该配置明确具有 <code>RecommendedNumber</code>。没有这个字段的普通棋子，即使棋盘上很多，也不会进入 Baseline 候选池。</li><li><code>持有数量 - 所有当前订单已需求数量 ≥ RecommendedNumber</code>。</li></ol><p class="formula">可用剩余数(Code) = 主棋盘数 + 仓库数 - 当前全部订单对该 Code 的需求数<br>候选成立 = 配置存在 ∧ RecommendedNumber存在 ∧ 可用剩余数 ≥ RecommendedNumber</p><p>这里的“扣除”只是生成时计算上的预留，不会真的提前删除棋子。目的在于避免 Baseline 抢走其它订单已经需要的那几件库存。</p><h3>当前版本哪些 Code 有资格</h3><div class="table-wrap"><table><thead><tr><th>Code</th><th>需要数量 RecommendedNumber</th><th>单件 Baseline 金币 RecommendedPrice</th><th>整单金币</th></tr></thead><tbody><tr><td>212 / 213 / 214 / 215</td><td>1</td><td>178 / 270 / 406 / 612</td><td>同单件价格</td></tr><tr><td>512 / 513 / 514</td><td>1</td><td>202 / 304 / 458</td><td>同单件价格</td></tr><tr><td>910 / 1311 / 1407 / 1812</td><td>1</td><td>202 / 318 / 86 / 458</td><td>同单件价格</td></tr><tr><td>307</td><td>2</td><td>58</td><td>116</td></tr><tr><td>607</td><td>2</td><td>62</td><td>124</td></tr><tr><td>1107</td><td>2</td><td>42</td><td>84</td></tr></tbody></table></div><p class="muted">当前导出的 14 个配置 Code 中，11 个要求 1 件，3 个要求 2 件。候选池不会读取普通随机订单的 Weight；代码使用 <code>ListRandomSelectOne</code> 从合格 Code 条目中随机选一个，因此在候选列表层面是等概率，不按持有数量加权。持有 10 件不会比刚好持有足量获得更高权重。</p><h3>从棋盘状态到订单落地：完整数字例子</h3><div class="table-wrap"><table><thead><tr><th>Code</th><th>主棋盘</th><th>仓库</th><th>当前其它订单需求</th><th>可用剩余</th><th>门槛</th><th>结果</th></tr></thead><tbody><tr><td>307</td><td>2</td><td>1</td><td>1</td><td><code>2+1-1=2</code></td><td>RecommendedNumber=2</td><td><strong>进入候选池</strong></td></tr><tr><td>607</td><td>1</td><td>0</td><td>0</td><td><code>1+0-0=1</code></td><td>RecommendedNumber=2</td><td>数量不足，排除</td></tr><tr><td>512</td><td>1</td><td>0</td><td>1</td><td><code>1+0-1=0</code></td><td>RecommendedNumber=1</td><td>已被其它订单预占，排除</td></tr><tr><td>其它 11 个资格 Code</td><td>0</td><td>0</td><td>0</td><td>0</td><td>1 或 2</td><td>未持有，排除</td></tr></tbody></table></div><ol class="list"><li>Slot15 为空；12:00 第一次扫描把计时器从 -1 写成 12:00，本次不出单。</li><li>12:01 后发生新的补位扫描，60 秒门槛通过，程序按上表重建候选池。</li><li>池里只有 Code 307，因此不再有随机性，必选 307。</li><li>订单需求写成两份 Code 307，即要求玩家提交 <strong>307 × 2</strong>。</li><li>每份使用 <code>RecommendedPrice=58</code>，所以整单金币为 <strong>58 × 2 = 116</strong>。</li><li>创建成功时计时器重置为 -1。该订单占住 Slot15；完成前不会再叠加第二张 Baseline。</li><li>完成后触发补位扫描。新的周期仍要先记录起点、至少等 60 秒，再由更晚的一次扫描重新检查当时的库存。</li></ol><h3>几个容易误解的情况</h3><ul class="list"><li><strong>棋盘很满，不等于一定有候选：</strong>大量低阶棋子若没有 RecommendedNumber 字段，全部不算。</li><li><strong>配置里有资格，不等于当前可用：</strong>例如 607 要 2 件，你只有 1 件，就不进入池。</li><li><strong>已经被其它订单需求的库存会被扣除：</strong>只有超过那些需求后的富余数量才供 Baseline 使用。</li><li><strong>不看 Player / DiffSum / MonthPay Filter：</strong>Baseline 走独立库存筛选，不走 Random Filter。</li><li><strong>不按库存数量加权：</strong>候选 Code 307 有 2 件或 20 件，进入池后都只占一个候选条目。</li><li><strong>候选池为空：</strong>本次不创建，Slot15 继续为空；计时已经满足，后续补位扫描会按最新库存再次检查。</li></ul><p class="formula">Baseline 的定位 = 用专属 Slot15 回收玩家已有的“可交付富余库存”，而不是制造一个新的生产目标。</p></div>'''
    baseline_items_markup = r'''<div class="section"><h2>Baseline 的 14 个指定棋子：名称与等级</h2><p><strong>这里的“棋子等级”是合成链等级 L；“玩家解锁等级”是 OrderItemConfig.UnlockLevel，两者不要混淆。</strong>例如全家桶是 L7 棋子，但对应订单配置的玩家解锁等级是 Lv.20。</p><div class="table-wrap"><table><thead><tr><th>Code</th><th>中文名称</th><th>合成链 / 棋子等级</th><th>玩家解锁等级</th><th>Baseline 要求数量</th><th>整单金币</th></tr></thead><tbody><tr><td>212</td><td>火腿奶酪羊角面包</td><td>面粉/食物链 · L12</td><td>Lv.1</td><td>1</td><td>178</td></tr><tr><td>213</td><td>粘稠的芝士汉堡</td><td>面粉/食物链 · L13</td><td>Lv.1</td><td>1</td><td>270</td></tr><tr><td>214</td><td>芝士汉堡和薯条</td><td>面粉/食物链 · L14</td><td>Lv.1</td><td>1</td><td>406</td></tr><tr><td>215</td><td>豪华芝士汉堡餐</td><td>面粉/食物链 · L15</td><td>Lv.1</td><td>1</td><td>612</td></tr><tr><td>307</td><td>全家桶</td><td>土豆链 · L7</td><td>Lv.20</td><td>2</td><td>116</td></tr><tr><td>512</td><td>蜜饯浆果咖啡</td><td>咖啡链 · L12</td><td>Lv.3</td><td>1</td><td>202</td></tr><tr><td>513</td><td>咖啡甜点</td><td>咖啡链 · L13</td><td>Lv.3</td><td>1</td><td>304</td></tr><tr><td>514</td><td>甜茶派对</td><td>咖啡链 · L14</td><td>Lv.3</td><td>1</td><td>458</td></tr><tr><td>607</td><td>精致茶饮</td><td>茶饮链 · L7</td><td>Lv.20</td><td>2</td><td>124</td></tr><tr><td>910</td><td>大海鲜塔</td><td>海鲜链 · L10</td><td>Lv.31</td><td>1</td><td>202</td></tr><tr><td>1107</td><td>豪华梦幻蛋糕</td><td>橙子/甜点链 · L7</td><td>Lv.25</td><td>2</td><td>84</td></tr><tr><td>1311</td><td>恐龙漂浮圈</td><td>泳圈链 · L11</td><td>Lv.31</td><td>1</td><td>318</td></tr><tr><td>1407</td><td>潜水探险舱</td><td>潜水装备链 · L7</td><td>Lv.41</td><td>1</td><td>86</td></tr><tr><td>1812</td><td>珍珠贝</td><td>贝壳链 · L12</td><td>Lv.41</td><td>1</td><td>458</td></tr></tbody></table></div><p class="muted">名称取自简体中文本地化 <code>item_{Code}_name</code>；棋子等级由物品链定义（如 Flour12、Potato07、Coffee12）确认。玩家解锁等级来自 OrderItemConfig。Baseline 运行时依赖实际持有量，代码没有在候选函数里再次单独比较玩家等级；通常能持有该棋子就意味着相关链已开放。</p></div>'''
    mechanism_markup = baseline_markup + baseline_items_markup + fill_scan_markup
    mechanism_markup = mechanism_markup.replace('玩家 Lv.20，DiffSum 落入 Random3 Filter2：First L7-8、Second L1-5、Third L1-3。', '玩家 Lv.20 命中 Random3 Filter3：First L7-9、Second L1-7、Third L1-5；该档不读取 DiffSum。').replace('Filter2 命中，建立 First 候选池：L7/L8。', 'Filter3 命中，建立 First 候选池：L7-L9。')
    focused_example = r'''<div class="section"><h2>单一完整案例：从触发到 Random3 + MonthPay Filter 命中</h2><p>下面是一条完整推演链。<strong>Player、DiffSum、MonthPay 是同一个 Filter 的同时条件（AND），不是三个独立抽签。</strong>当前导出的客户端 <code>OrderRandomConfig.json</code> 没有保留 MonthPay 字段，因此带 MonthPay 的数值是“按代码机制构造的演示配置”，字段名和判断顺序以反编译代码为准。</p><div class="table-wrap"><table><thead><tr><th>阶段</th><th>当前状态</th><th>判断</th><th>结果</th></tr></thead><tbody><tr><td>0. 触发事件</td><td>订单初始化/完成上一单后，<code>SlotOrderModel</code> 扫描逻辑槽位 1..19。</td><td>Slot4 为空；Slot4 的固定映射是 <code>Random3</code>。</td><td><strong>不是在 Random1-5 中随机抽类型</strong>，而是“扫描到 Slot4 → 进入 Random3 创建器”。</td></tr><tr><td>1. 类型开放</td><td>Random3 <code>UnlockLevel=4</code>；玩家 Lv.40。</td><td><code>40 ≥ 4</code>。</td><td>Random3 允许尝试。</td></tr><tr><td>2. CD</td><td><code>RefreshTime=900</code> 秒；StartTimer=10:00:00；当前 10:15:01。</td><td>已过去 901 秒，<code>901 ≥ 900</code>。</td><td>CD 通过；仍需继续做 Filter 和物品候选检查。</td></tr><tr><td>3. 读取玩家状态</td><td><code>Player=40</code>；<code>DiffSum=1800</code>；<code>MonthPay=650</code>。</td><td>创建器一次读取三个值，然后按 Filter 顺序逐项比较。</td><td>进入 Filter 选择。</td></tr><tr><td>4. Filter1</td><td><code>PlayerMax=35</code>；<code>DiffSumMax=1500</code>；<code>sMonthPay=0,eMonthPay=299</code>。</td><td>Player 条件已失败：<code>40 ≤ 35</code> 为假。</td><td>Filter1 失败，不再需要看其它字段。</td></tr><tr><td>5. Filter2</td><td><code>PlayerMin=36,PlayerMax=60</code>；<code>DiffSumMax=1500</code>；<code>sMonthPay=300,eMonthPay=699</code>。</td><td>Player 成立，但 DiffSum 失败：<code>1800 ≤ 1500</code> 为假。</td><td>Filter2 失败。</td></tr><tr><td>6. Filter3</td><td><code>PlayerMin=36,PlayerMax=60</code>；<code>DiffSumMin=1501,DiffSumMax=2000</code>；<code>sMonthPay=300,eMonthPay=699</code>。</td><td>Player：<code>36≤40≤60</code>；DiffSum：<code>1501≤1800≤2000</code>；MonthPay：<code>300≤650≤699</code>。</td><td><strong>三组条件全部成立，选中 Filter3。</strong></td></tr><tr><td>7. Filter 命中结果</td><td>Filter3 配置：First L8-10、Second L1-7、Third L1-5。</td><td>按命中的 Filter 读取等级边界。</td><td>后续只能在这些等级范围内建候选池。</td><tr><td>8. 件数</td><td><code>ItemAmounts=One 50% / Two 50% / Three 0%</code>；本次随机结果为“两件”。</td><td>First 永远存在，两件需要 First+Second。</td><td>本单不创建 Third。</td></tr></tbody></table></div><p class="muted">代码中的 MonthPay 字段名是 <code>sMonthPay</code> / <code>eMonthPay</code>；缺字段表示该条件不参与（不是把缺失当成 0）。若一个 Filter 的 Player、DiffSum 或 MonthPay 任一条件失败，就不会命中该 Filter。</p><div class="section"><h3>Filter3 命中后继续生成</h3><ol class="list"><li>First 建立 L8-L10 原始候选池：当前配置级理论上 L8×5 + L9×5 + L10×5 = 15 个，每个初始 Weight=100。</li><li>逐个检查 ProgressUnlock、物品 UnlockLevel、母体生成器、ForbiddenSlot、Weight、其它未完成订单占用和上一完成订单重复。</li><li>假设 15 个中 3 个进入非优先分类：L8 的 1 个母体未解锁、L9 的 1 个被其它订单占用、L10 的 1 个与上一单重复；优先池剩 12 个，总 Weight=1200。</li><li>假设加权抽中 First=L9。随后以当前订单已占用需求为上下文，建立 Second 的 L1-L7 候选池；再做同样的解锁、槽位、跨槽位和上一单检查。</li><li>若 Second 最终抽中 L4，则订单落地为 <code>Slot4 / Random3 / Filter3 / First=L9 + Second=L4</code>。</li></ol><p class="formula">本次成功 = Slot4空 ∧ Random3已解锁 ∧ CD通过 ∧ (Player条件∧DiffSum条件∧MonthPay条件命中Filter3) ∧ First候选非空 ∧ Second候选非空。</p></div><div class="section"><h3>为什么不是 Filter2？MonthPay 如何改变结果？</h3><p>本例中 Filter2 的 Player 区间也满足，但 DiffSum=1800 超过其 1500 上限，所以失败。若把 DiffSum 改成 1400，则 Filter2 的 Player、DiffSum 都满足，但 MonthPay=650 仍在 300-699 区间，Filter2 才会命中。若再把 MonthPay 改成 800，则 Filter2 也失败，即使 Player 和 DiffSum 都满足；这就是 MonthPay 作为第三个 AND 条件的作用。若所有 Filter 都失败，则停止在 Filter 选择阶段，后面的 First/Second 抽取不会发生。</p></div></div>'''
    condition_markup = '<div class="section"><h2>Player / DiffSum / MonthPay 如何得到</h2><p>这三个值不是同一种“玩家属性”：Player 是当前关卡等级，DiffSum 是订单难度累计器，MonthPay 是账户/服务器下发的月付金额。创建 Random 订单时，客户端在同一次 <code>CanCreate</code> 判断中读取三者，然后对每个 Filter 做区间 AND 判断。</p><div class="table-wrap"><table><thead><tr><th>条件</th><th>客户端来源</th><th>计算/更新方式</th><th>刷新与边界</th><th>例子</th></tr></thead><tbody><tr><td><strong>Player</strong></td><td><code>GM.LevelModel:GetCurrentLevel()</code></td><td>直接读取当前关卡等级；例如当前为 Lv.40，则 Player=40。</td><td>升级后读取新值；有边界时使用 <code>PlayerMin ≤ Player ≤ PlayerMax</code>。</td><td>Filter 要求 36–60，玩家 Lv.40，条件成立。</td></tr><tr><td><strong>DiffSum</strong></td><td><code>MainOrderModel:GetTotalDiffScore()</code></td><td>订单 <code>GetDiffScore()</code> 是需求棋子的 <code>OrderItemConfig.DiffScore</code> 之和；完成普通订单时累加到持久化 <code>TotalDiffScore</code>。</td><td><code>TryRefreshTotalDiffScore</code> 到达本地下一个 2:00 后归零；Filter 使用 DiffSumMin/Max 闭区间。</td><td>旧累计 1200，完成订单的 DiffScore 合计 600，则新 DiffSum=1800。</td></tr><tr><td><strong>MonthPay</strong></td><td><code>GM.GameModel:GetMonthPay()</code> 返回 <code>m_monthPay</code></td><td>初始化/同步时从数据字段 <code>month_pay</code> 读入；客户端不根据本地订单金币重新求和。</td><td>Filter 字段是 <code>sMonthPay/eMonthPay</code>；缺字段表示该条件不参与。</td><td>MonthPay=650，Filter 区间 300–699，条件成立。</td></tr></tbody></table></div><div class="section"><h3>完整数值例子</h3><ol class="list"><li>当前 Lv.40，所以 Player=40。</li><li>上次刷新后的 DiffSum=1200；刚完成订单的三个需求 DiffScore 为 180、240、180，因此 order.DiffScore=600。</li><li>完成结算后 DiffSum=1200+600=1800。</li><li>同步数据 month_pay=650，所以 MonthPay=650。</li><li>Filter3 要求 Player 36–60、DiffSum 1501–2000、MonthPay 300–699；三组条件分别为 36≤40≤60、1501≤1800≤2000、300≤650≤699，全部成立。</li></ol></div><p class="muted">证据边界：客户端可确认读取入口、DiffScore 累加和每日归零时机；但服务端如何设计每个棋子的 DiffScore，以及 month_pay 的统计周期/退款口径，当前材料无法还原。</p></div>'
    focused_example = focused_example.replace('</td><tr><td>8. 件数', '</td></tr><tr><td>8. 件数')
    mechanism_markup = mechanism_markup.replace('Slot1 / Slot2 / Slot4 / Slot5 / Slot8', 'Slot1 / Slot2 / Slot3 / Slot4 / Slot5 / Slot8')
    mechanism_markup = mechanism_markup.replace('对应 Random1、Random2、Random3、Random4、Random5New；当前随机配置中共 5 类普通随机类型。Slot3 在该随机创建器中不是普通随机映射，不能把 19 减成或加成普通随机数。', '对应 Random1、Random2（Slot2/Slot3）、Random3、Random4、Random5New；当前普通随机实际占用 6 个槽位。Slot3 是 Random2 的额外普通随机槽，不是 CharacterIntimacySlot。')
    mechanism_markup = mechanism_markup.replace('当前配置映射是最多 5 个随机槽位', '当前配置映射是最多 6 个随机槽位')
    mechanism_markup = '<div class="section"><h2>Slot 编号与 Type 编号不要混淆</h2><p><code>CharacterIntimacyRandom</code> 的 Type 枚举值是 12，但它使用的是 <code>CharacterIntimacySlot=10</code>，不是 Slot3。<code>Random3</code> 固定使用 <code>Slot4=4</code>。因此亲密度订单未完成时，不会按“占用 Slot3”阻塞 Random3；两者是不同槽位、不同创建路径。亲密度订单的需求仍可能参与跨订单需求占用，从而影响 Random3 的候选优先级，但这不等于槽位互斥。</p></div>' + mechanism_markup
    clarify_markup = r'''<div class="section"><h2>如何解读 P1 / P2 / P3 候选分布</h2><p>这里的 <code>P1</code>、<code>P2</code>、<code>P3</code> 是订单需求位置（Position 1/2/3），不是概率，也不是棋盘槽位编号。每个位置后面的 <code>L等级×数量</code> 表示：在该位置的等级范围内，标准 <code>OrderItemConfig</code> 候选有多少个。</p><div class="table-wrap"><table><thead><tr><th>显示</th><th>含义</th><th>如何转成概率</th></tr></thead><tbody><tr><td><code>P1: L2×1,L3×9,L4×9,L5×9,L6×9</code></td><td>第一件需求的候选池中：2级有1个棋子编码，3级有9个，4级有9个，5级有9个，6级有9个；合计 37 个候选。</td><td>当前这些候选的 Weight 都是 100，因此单个候选概率为 <code>100/(37×100)=1/37</code>；按等级汇总：L2 为 1/37，L3-L6 各为 9/37。</td></tr><tr><td><code>P2: L2×1,L3×9,L4×9,L5×9</code></td><td>第二件需求的候选池合计 28 个候选，最高到 L5。</td><td>若没有运行时排除且 Weight 相同，按等级概率为 1/28、9/28、9/28、9/28。</td></tr><tr><td><code>P3: L2×1,L3×9</code></td><td>第三件需求的候选池合计 10 个候选，只包含 L2 和 L3。</td><td>若没有运行时排除且 Weight 相同，L2 为 1/10，L3 为 9/10。</td></tr></tbody></table></div><p class="muted">这些是“配置级原始候选池”统计，不等于每次实际落地概率。ProgressUnlock、母体未解锁、ForbiddenSlot、其他订单占用、上一单重复抑制和 Weight 变化都会改变有效候选数与归一化分母。位置之间也不是完全独立：P1 抽中后会进入当前订单需求上下文，P2/P3 会重新筛选。</p></div><div class="section"><h2>MonthPay 是否参与当前 Filter</h2><p>要分成“代码能力”和“当前配置”两层看：</p><ul class="list"><li><strong>代码能力：</strong>创建器支持 <code>sMonthPay/eMonthPay</code> 区间，判断形式是 <code>sMonthPay ≤ MonthPay ≤ eMonthPay</code>；如果某个 Filter 配置了这两个字段，它们会和 Player、DiffSum 一起按 AND 关系参与命中。</li><li><strong>当前配置：</strong>本次导出的 <code>OrderRandomConfig.json</code> 中没有任何 <code>sMonthPay</code>、<code>eMonthPay</code>、<code>MonthPayMin</code> 或 <code>MonthPayMax</code> 字段。因此当前定量矩阵里的实际 Filter 不使用 MonthPay；页面中的 MonthPay=650、300–699 等内容是机制演示配置，不能当作当前版本的实测条件。</li><li><strong>缺字段语义：</strong>缺少 MonthPay 字段表示该条件不参与，不是把 MonthPay 当成 0，也不是自动失败。</li></ul></div><div class="section"><h2>一个槽位的所有 Filter 都不满足时</h2><ol class="list"><li>创建器逐个检查该类型的 Filter；如果没有任何一个 Filter 的全部条件成立，则在“Filter 选择”阶段失败。</li><li>本次不会继续创建 First、Second、Third，也不会用一个不匹配的 Filter 兜底；该槽位保持空或保持待补位状态。</li><li>这次失败不会把订单放到别的类型，也不会因为 Random3 失败就改抽 Random1/Random4；类型与槽位映射仍然固定。</li><li>后续只有在新的补位/重试事件中再次尝试。当前证据能确认“本次返回失败、后续可重试”，但不能仅凭现有材料断言失败后是否立刻重置该槽位计时器；因此报告不把失败等同于 CD 重置。</li><li>其他槽位独立处理：一个槽位没有命中 Filter，不会阻止其他已满足条件的槽位创建订单。</li></ol><p class="formula">该槽位本次结果 = Filter1失败 ∧ Filter2失败 ∧ … ∧ FilterN失败 → 不生成订单；不是“从失败 Filter 中随机选一个”。</p><p class="muted">例：Random3 当前 Player=40、DiffSum=1800、MonthPay=650；若所有 Filter 的 Player/DiffSum/MonthPay 区间都无法同时覆盖这三个值，则 Random3 本轮直接失败，即使 First 的候选池本身仍然存在。</p></div>'''
    special_rules_markup = r'''<div class="section"><h2>非 Random 特殊订单：统一推演框架</h2><p>特殊订单不能套用“RefreshTime 到期 → 选 Filter → 抽 First/Second/Third”这一套。统一先问五个问题：<strong>哪个事件触发？哪个模型判定开放？哪个槽位可用？需求从哪里来？完成/失败后状态如何变化？</strong>只有亲密度、Timed 等复用普通随机需求池的类型，才会进入类似 Random 的等级候选筛选。</p><div class="flow"><div class="step"><h3>1 · 事件进入</h3><span>初始化、任务完成、订单完成、活动状态变化或特殊计时器到期。</span></div><div class="arrow">→</div><div class="step"><h3>2 · 活动资格</h3><span>检查任务、活动开关、回归窗口、积分/令牌或模型 CanCreate。</span></div><div class="arrow">→</div><div class="step"><h3>3 · 槽位资格</h3><span>检查对应槽位是否为空/Finished；特殊订单不一定有独立 CD。</span></div><div class="arrow">→</div><div class="step"><h3>4 · 读取需求</h3><span>固定配置、Special 配置、活动配置，或从棋盘当前物品动态选择。</span></div><div class="arrow">→</div><div class="step"><h3>5 · 落地/失败</h3><span>成功写入订单；失败保留计时/活动状态，等待下一次合法事件。</span></div></div></div><div class="section"><h2>特殊类型规则总表</h2><div class="table-wrap"><table><thead><tr><th>类型</th><th>槽位/入口</th><th>从 0 开始的判定顺序</th><th>需求来源</th><th>刷新/重试语义</th><th>当前证据边界</th></tr></thead><tbody><tr><td><strong>Fixed</strong></td><td>普通固定槽；<code>MainOrderCreatorFixed</code></td><td>读取 <code>CurrentFixedOrderId</code> → 加 1 → 查 <code>OrderFixedConfig</code> → 检查该配置 Slots 包含当前槽位 → 检查玩家等级 ≥ UnlockLevel → 创建。</td><td>OrderFixedConfig 的 Requirement1/2/3。</td><td>按固定订单 Id 顺序推进；不是按 CD 随机刷新。当前 Id 不满足当前槽位/等级时，本轮不创建。</td><td>配置和创建器可确认；具体哪个事件调用补位由 SlotOrderModel/MainOrderModel 负责。</td></tr><tr><td><strong>Special</strong></td><td>SpecialSlot=6；<code>MainOrderCreatorSpecial</code></td><td>读取 <code>CurrentSpecialOrderId</code> → 查 SpecialConfig(id+1) → 解析 <code>Trigger=taskFinish-a_b</code> → 检查 <code>MainTaskModel.IsTaskFinished(a,b)</code> → 创建并推进 Id。</td><td>OrderSpecialConfig 的固定 Requirement 和 AvatarId。</td><td>任务完成是触发器；不是周期 CD。当前导出有 6 个示例：taskFinish-2_7、11_6、18_7、24_3、29_8、33_9。</td><td>客户端可确认 Trigger 解析与任务完成判断；任务系统何时发起补位由任务/主订单模型驱动。</td></tr><tr><td><strong>Branch</strong></td><td>BranchSlot=7；BranchOrderConfig</td><td>先调用 Branch <code>CanCreate</code>；通过后取当前 Branch 配置，Requirement/Id/AvatarId 创建。</td><td>BranchOrderConfig.Requirement；示例 Id=1、Slot=7、Requirement=8313。</td><td>由支线/活动状态驱动，不是普通 RefreshTime。</td><td>当前提取版本的 <code>MainOrderCreatorBranch.CanCreate</code> 为空实现并返回 false，不能把配置存在误写成线上必定出现。</td></tr><tr><td><strong>CharacterIntimacyRandom</strong></td><td>CharacterIntimacySlot=10；独立 StartTimer；配置 RefreshTime=3600 秒</td><td>槽位可用 → CharacterIntimacyModel 开放且随机订单总开关开放 → 独立计时器达到 → 复用 Random Filter/候选创建器。</td><td>当前配置 Type12：First 6–7、Second≤5、Third≤5；数量 30/30/40。</td><td>独立于 Random3 的 Slot4；完成/补位后按该槽位自己的 timer 重试。</td><td>亲密度模型具体开放条件和 StartTimer 初始化事件未在当前材料完全展开。</td></tr><tr><td><strong>TimedOrder</strong></td><td>TimedOrderSlot=13；Type16；配置 RefreshTime=1 秒</td><td>槽位必须是 13 → 读取 Type16 → 玩家等级 ≥12 → <code>ActivityManager.GetModel(TimedOrder).CanCreateOrder(slot)</code> → 活动模型创建订单。</td><td>当前 Type16 Filter：First 5–7、Second 4–5、Third 3–4；数量 30/30/40。</td><td>1 秒是占位/即时尝试，不是每秒必定生成；实际资格由 TimedOrder 活动模型决定。</td><td>活动模型和远端活动配置未导出，不能从客户端静态包还原完整活动周期。</td></tr><tr><td><strong>BaselineOrder</strong></td><td>BaselineOrderSlot=15；独立 <code>RandomBaselineLastGenerateTimer</code></td><td>首次计时器为 -1 → 写入当前 ServerTime 并返回失败；之后等待至少 60 秒 → <code>GetBaselineAvailableItems</code> 非空 → 允许创建。</td><td>从棋盘当前物品中动态选一个 Code，并复制其 RecommendedNumber 数量。</td><td>创建后计时器重置为 -1，下一轮重新开始“记录时间 → 等 60 秒”；棋盘无可用物品则失败。</td><td>60 秒和动态候选逻辑可由代码确认；具体可用物品过滤由 RandomOrderHelper 决定。</td></tr><tr><td><strong>Lucky</strong></td><td>LuckyOrderSlot=17；LuckyOrderPoints/Timer</td><td>槽位 17 → <code>CanTriggerLucky</code> → 读取 LuckyOrderConfig、玩家等级、Points、Timer → 满足积分/RefreshTime 条件 → 关闭触发标志 → 复用 Filter/候选生成。</td><td>LuckyOrderConfig 的 Filter；当前包未导出该配置，无法给出完整等级数值。</td><td>触发时 Points 清 0、Timer 写当前 ServerTime；候选不足也会进入冷却/重试逻辑。</td><td>可确认状态变量和条件分支；LuckyTriggerChance/Filter 的具体值需要额外配置包。</td></tr><tr><td><strong>ReturnUserFree</strong></td><td>仅 Slot1/2/3；ReturnUserFreeOrderTimer</td><td>槽位属于 1–3 → ReturnUserModel.IsOpen → 在回归奖励时间内 → Timer=0 时写当前 ServerTime 并本次失败；Timer 未设置或距当前 ≥28800 秒（8 小时）才允许创建。</td><td>从棋盘物品中随机选等级 ≤7 的物品；不是 OrderRandomConfig 的静态候选池。</td><td>创建成功后由状态/计时器控制下一次；回归窗口结束则整个入口关闭。</td><td>8 小时和等级上限可确认；回归奖励窗口与 CreatorReturnFreeOrderRefreshTime 的最终业务配置未导出。</td></tr><tr><td><strong>ChestCustomer</strong></td><td>活动模型检查指定普通槽；创建入口 <code>CheckCreateChestOrder(slot)</code></td><td>先由 ChestCustomerModel 判断能否填充 → 读取对应 ChestOrderRandomConfig → 有配置则按活动订单创建 → 无配置时日志显示回退普通随机配置。</td><td>ChestOrderRandomConfig / hard / lessitem 变体；不是普通 Filter 的 MonthPay 判定。</td><td>当前活动表记录 120 秒，但实际是否可填充由 CustomerUpgradeReward/ChestCustomer 模型控制；可能替换普通订单。</td><td>可确认“检查→配置→创建/回退”路径；活动等级、宝箱进度和最终配置选择需活动数据。</td></tr><tr><td><strong>Contiorder / ExtraCustomer</strong></td><td>ContiorderSlot=18、ExtraCustomerSlot=19</td><td>对应 ActivityModel.CanCreateOrder/状态机通过 → 读取活动专属订单 → 写入活动槽位；完成后由 MainOrderModel 继续补位。</td><td>活动专属配置与奖励。</td><td>完成、接受/拒绝、活动状态改变都可能改变下一单；不能用普通 CD 推导。</td><td>当前材料只有事件名和入口，缺少完整活动配置，必须标记为待补数据。</td></tr></tbody></table></div></div><div class="section"><h2>完整推演例 1：Special 任务订单 Special 3</h2><ol class="list"><li>玩家完成主线任务 <code>18_7</code>，触发事件进入订单补位流程。</li><li>Special 创建器读取 <code>CurrentSpecialOrderId</code>。假设当前值为 2，因此候选 Id 为 3。</li><li>读取 <code>OrderSpecialConfig[3]</code>：<code>Trigger=taskFinish-18_7</code>、<code>Requirement1=sp3_2_10</code>、<code>Requirement2=sp3_3_6</code>、<code>AvatarId=103</code>。</li><li>解析 Trigger：任务组为 18，任务号为 7；调用 <code>MainTaskModel.IsTaskFinished(18,7)</code>，返回 true。</li><li>创建订单：类型为 <code>Special</code>，需求是 <code>sp3_2_10 + sp3_3_6</code>，头像 103；同时把 CurrentSpecialOrderId 推进为 3。</li><li>奖励配置为 <code>30 gems + 150 energy</code>；它不是普通订单金币，因此不进入普通金币/体力期望。</li></ol><p class="formula">Special3 成功 = 当前 Id=2 ∧ 配置存在 ∧ 任务 18_7 已完成 ∧ SpecialSlot 可用。</p><p class="muted">如果当前 Id 不是 2，或者任务尚未完成，本轮不会跳过到 Special4，也不会随机选择其它 Special。</p></div><div class="section"><h2>完整推演例 2：Baseline 从空槽到订单</h2><ol class="list"><li>Slot15 为空，进入 BaselineOrder 的 CanCreate。</li><li>读取 <code>RandomBaselineLastGenerateTimer=-1</code>；代码先写入当前服务器时间，例如 12:00:00，然后返回 false。此时不会生成订单。</li><li>12:00:30 再次尝试：距离上次记录 30 秒，小于 60 秒，失败。</li><li>12:01:00 再次尝试：距离达到 60 秒；调用 <code>GetBaselineAvailableItems</code>，假设返回苹果 L4（RecommendedNumber=2）和牛奶 L5（RecommendedNumber=1）。候选非空，CanCreate=true。</li><li>Create 阶段从候选中随机选中苹果 L4，复制 RecommendedNumber=2，创建 <code>BaselineOrder</code>；创建后计时器重置为 -1。</li><li>下一次需要重新记录时间并再等待 60 秒；如果棋盘没有可用候选，即使 60 秒已到也不生成。</li></ol><p class="formula">Baseline 成功 = Slot15 可用 ∧ (当前时间 - 上次记录时间 ≥ 60s) ∧ 可用棋盘候选非空。</p></div><div class="section"><h2>完整推演例 3：TimedOrder 与亲密度订单</h2><div class="grid"><article class="section"><h3>TimedOrder</h3><ol class="list"><li>Slot13 为空；玩家 Lv.12，满足 Type16 的 UnlockLevel=12。</li><li>配置 RefreshTime=1 只表示可以立即尝试，不能单独产生订单。</li><li>调用 TimedOrder 活动模型的 <code>CanCreateOrder(13)</code>；若活动未开放、活动已达订单上限或该槽已有活动订单，返回 false。</li><li>只有返回 true，才调用活动模型 <code>CreateOrder(13)</code>；当前静态配置的需求范围为 First L5–7、Second L4–5、Third L3–4。</li></ol></article><article class="section"><h3>CharacterIntimacyRandom</h3><ol class="list"><li>CharacterIntimacySlot=10 为空；亲密度系统开放且普通随机订单总开关开放。</li><li>独立 StartTimer + RefreshTime=3600 秒达到，进入普通随机创建器。</li><li>按 Type12 Filter 建立 First L6–7、Second≤L5、Third≤L5 的候选池，数量权重为 30%/30%/40%。</li><li>继续执行解锁、跨订单占用、上一单抑制和 Weight 抽取；成功后写入 Slot10。它不会占用 Slot4，因此不会阻塞 Random3 的槽位创建。</li></ol></article></div></div><div class="section"><h2>特殊订单失败时的共同规则</h2><ul class="list"><li>特殊创建器返回失败时，不会创建一个“空需求”订单，也不会自动改成普通 Random 类型；当前槽位继续等待该类型自己的下一次合法事件。</li><li>任务型订单失败通常意味着任务条件未完成、CurrentId 不匹配或槽位不可用；不会跳过 Id。</li><li>活动型订单失败通常意味着活动模型未开放、活动上限/令牌/积分不满足或活动配置缺失；是否立即重试由活动模型决定。</li><li>动态棋盘型订单（Baseline、ReturnUserFree）在计时满足但候选为空时仍失败，必须等候选状态变化或下一次尝试。</li><li>证据边界：当前包能还原客户端判定顺序，但远端活动配置、服务器下发的活动状态、奖励结算条件可能改变最终行为。</li></ul></div>'''
    role_markup = r'''<div class="section"><h2>先记住这张“订单定位”表</h2><p>这里先回答“它为什么存在、多久会来、值不值得做”。<strong>次数是理论最多尝试次数，不是保证生成次数</strong>：槽位被占用、活动未开放或候选不足时，实际次数会更少。</p><div class="table-wrap"><table><thead><tr><th>订单</th><th>触发/尝试频率</th><th>金币/体力</th><th>直观定位</th><th>玩家应该怎么理解</th></tr></thead><tbody><tr><td><strong>Random1</strong></td><td>CD 3600 秒；理论最多 24 次/天；玩家 Lv.3 开放</td><td>约 1.25–1.31</td><td><span class="tag">福利型</span></td><td>来得慢，但单位体力给钱最多，优先完成。</td></tr><tr><td><strong>Random2</strong></td><td>CD 1800 秒；理论最多 48 次/天；玩家 Lv.3 开放</td><td>约 0.85–0.86</td><td><span class="tag">平衡型</span></td><td>频率和回报都居中，属于常规周转订单。</td></tr><tr><td><strong>Random3</strong></td><td>CD 900 秒；理论最多 96 次/天；玩家 Lv.4 开放</td><td>约 0.32–0.95</td><td><span class="tag">分段型</span></td><td>早中期尚可，进入高难度段后可能明显吃体力。</td></tr><tr><td><strong>Random4</strong></td><td>CD 300 秒；理论最多 288 次/天；玩家 Lv.5 开放</td><td>约 0.22–0.70</td><td><span class="tag">资源消耗型</span></td><td>来得最频繁之一，但高等级段性价比低，像资源消耗口。</td></tr><tr><td><strong>Random5New</strong></td><td>CD 1200 秒；理论最多 72 次/天；玩家 Lv.10 开放</td><td>约 0.71</td><td><span class="tag">后期常规型</span></td><td>后期开启的普通订单，回报中等，不是主要福利来源。</td></tr><tr><td><strong>CharacterIntimacyRandom</strong></td><td>CD 3600 秒；理论最多 24 次/天；亲密度系统开放后</td><td>约 1.00</td><td><span class="tag">成长福利型</span></td><td>不是 Random3 的竞争槽位，主要服务角色亲密度/活动体验，回报接近 1。</td></tr><tr><td><strong>TimedOrder</strong></td><td>配置 1 秒，但由限时活动模型决定；不能换算成固定次数</td><td>约 1.08（静态配置理论值）</td><td><span class="tag">活动冲刺型</span></td><td>活动开时优先看活动收益和倒计时，不要把 1 秒理解成每秒来一单。</td></tr><tr><td><strong>ChestCustomer</strong></td><td>配置 120 秒，理论最多 720 次/天；实际受宝箱/顾客活动资格限制</td><td>约 0.14</td><td><span class="tag">高消耗型</span></td><td>高阶需求、单位体力回报最低，除非为了活动/宝箱奖励，否则不要当福利单。</td></tr><tr><td><strong>BaselineOrder</strong></td><td>补位扫描时检查；上次记录后至少 60 秒，且必须有棋盘候选</td><td>动态，不能用普通 Filter 比较</td><td><span class="tag">补位型</span></td><td>它不等“全局没订单”，只要 Slot15 空、计时到、棋盘有候选，就可能生成。</td></tr><tr><td><strong>Fixed / Special</strong></td><td>任务或固定 Id 触发；不是日常 CD</td><td>普通金币口径不适用；Special 主要给宝石/体力</td><td><span class="tag">剧情进度型</span></td><td>完成它们是为了推进剧情、解锁奖励，不要拿它们和 Random 订单比刷钱效率。</td></tr><tr><td><strong>Lucky</strong></td><td>订单完成累积积分/计时触发；次数依赖 Lucky 配置</td><td>配置缺失，不能静态估算</td><td><span class="tag">奖励型</span></td><td>把它看成额外惊喜入口，而不是固定刷新槽。</td></tr></tbody></table></div><p class="muted">金币/体力来自当前导出配置的理论期望范围：基础子体=1体力，等级 L 棋子按 2^(L-1) 计价；不代表玩家已有库存和实际活动奖励后的净收益。</p></div><div class="section"><h2>Fixed / Special 到底多不多？</h2><p>当前配置是 <strong>16 个 Fixed + 6 个 Special = 22 个一次性/进度型订单配置</strong>。它们不是每天重复刷新的订单池：Fixed 按 Id 和槽位顺序投放，Special 按任务触发。换句话说，数量“足够覆盖前期剧情进度”，但相对 Random 的日常循环并不多。</p><ul class="list"><li>Fixed：16 个；按解锁等级分布为 Lv.1 有 4 个、Lv.2 有 6 个、Lv.3 有 3 个、Lv.4 有 3 个。</li><li>Special：6 个；当前已看到 6 个任务触发器：<code>2_7</code>、<code>11_6</code>、<code>18_7</code>、<code>24_3</code>、<code>29_8</code>、<code>33_9</code>。</li></ul></div><div class="section"><h2>Baseline 会不会在“没有订单、Random 都冷却”时触发？</h2><p><strong>会，但不是因为“没有订单”这个条件。</strong>Baseline 的真实条件是：</p><ol class="list"><li>自己的 <code>Slot15</code> 为空或可补位；</li><li>发生一次订单补位扫描，例如初始化、完成订单后的 <code>_TryFillOrders</code>；</li><li>首次检查时若计时器是 <code>-1</code>，只记录当前服务器时间，本次不生成；</li><li>之后距离上次记录至少 60 秒；</li><li><code>GetBaselineAvailableItems</code> 返回至少一个棋盘候选。</li></ol><p class="formula">Baseline 生成 = Slot15 可用 ∧ 补位扫描发生 ∧ 距上次记录≥60s ∧ 棋盘候选非空</p><p>因此：</p><ul class="list"><li>Random1–Random5 全部在 CD 中，<strong>不会直接触发 Baseline</strong>；</li><li>全局还有其它订单，<strong>也不妨碍 Baseline</strong>；</li><li>只要 Slot15 空、计时达到、棋盘有候选，并且刚好发生补位扫描，Baseline 就可以生成；</li><li>如果没有任何补位事件，代码证据不能支持“它每 60 秒自动后台生成一单”。60 秒是资格门槛，不是独立后台定时器。</li></ul></div>'''
    html = html.replace('<section id="matrix" class="panel"><div class="note">', '<section id="matrix" class="panel">' + role_markup + '<div class="note">')
    html = html.replace('<section id="mechanism" class="panel" hidden>', '<section id="mechanism" class="panel" hidden>' + TIMED_ORDER_MARKUP + focused_example + condition_markup + clarify_markup + special_rules_markup + mechanism_markup, 1)
    html = html.replace('只有亲密度、Timed 等复用普通随机需求池的类型，才会进入类似 Random 的等级候选筛选。', '只有亲密度等复用普通随机需求池的类型，才会进入类似 Random 的等级候选筛选；TimedOrder 的需求由活动模型创建。')
    html = html.replace('槽位必须是 13 → 读取 Type16 → 玩家等级 ≥12 →', '槽位必须是 13 → 读取 Type16（本地 UnlockLevel=1）→')
    html = html.replace('当前 Type16 Filter：First 5–7、Second 4–5、Third 3–4；数量 30/30/40。', 'Type16 本地 Filters 为空；需求、难度、数量与奖励由 TimedOrder 活动模型/远端配置提供。')
